/* Textes prêts à lire — 10 par exercice (by Stephen) */
(function(){var D=window.AO_DATA;D.exerciseTexts={"mot":[{"t":"Confiance","x":["La confiance, c’est un crédit qu’on s’ouvre à soi-même avant de l’ouvrir aux autres.","On la reconnaît à un détail : on arrête de vérifier trois fois la porte.","Quand mon voisin m’a laissé les clés de son appartement pour arroser ses plantes, il ne m’a pas fait signer de papier. Il m’a juste dit « à jeudi ».","Chez moi, la confiance a eu la taille d’un trousseau : petit, lourd, et plus précieux qu’il n’en a l’air.","Depuis, je me demande à qui j’ai donné mes clés, et à qui je devrais en rendre."]},{"t":"Héritage","x":["Un héritage, ce n’est pas ce qu’on reçoit : c’est ce qu’on décide d’entretenir.","Ma grand-mère m’a laissé une casserole bosselée. Pas d’argent, pas de terrain : une casserole.","Dedans, elle a fait mijoter cinquante ans de dimanches.","Je ne l’ai pas rangée : je m’en sers. Parce qu’un héritage qu’on n’utilise pas devient un meuble, et qu’un héritage qu’on utilise devient une façon de vivre.","Alors ma question n’est pas « qu’ai-je reçu ? » mais « qu’est-ce que je fais mijoter ? »"]},{"t":"Rareté","x":["Ce qui est rare n’est pas toujours précieux, mais ce qui est précieux a presque toujours été rare à un moment.","Prenez le temps. Il n’y en a pas dans les magasins.","Un matin de décembre, j’ai passé une heure entière sans téléphone, assis devant une tasse de thé. Personne ne m’a écrit, rien n’a brûlé.","Cette heure-là m’a coûté plus cher que n’importe quel achat : elle m’a coûté mon habitude.","Depuis, je protège une heure par semaine comme on protège une pièce rare."]},{"t":"Patience","x":["La patience, ce n’est pas attendre : c’est continuer pendant que ça ne se voit pas.","Quand j’ai commencé la guitare, mes doigts saignaient et mon voisin soupirait.","Pendant trois mois, j’ai joué le même accord. Un seul.","Au quatrième mois, un autre accord est arrivé, comme un invité qui frappe à la porte sans prévenir.","Depuis, je vois la patience comme une graine : on n’entend pas pousser, mais un jour la fenêtre est pleine de vert."]},{"t":"Frontière","x":["Une frontière n’est pas un mur : c’est un endroit où l’on se présente.","À dix-huit ans, j’ai traversé une frontière avec un sac et une adresse écrite sur un papier plié. Le douanier m’a regardé trois secondes.","Ces trois secondes m’ont appris qu’une frontière sépare, mais qu’elle sert surtout à dire : « voilà qui je suis, voilà d’où je viens ».","Aujourd’hui, quand je pose une limite à quelqu’un, je me rappelle le douanier : je ne ferme pas la porte, je dis où elle commence."]},{"t":"Lenteur","x":["La lenteur a mauvaise presse. On lui préfère la vitesse, qui a de meilleurs publicitaires.","Pourtant, c’est en marchant lentement que j’ai vu, pour la première fois, la fleur sur le muret de ma rue.","Elle était là depuis des années. Moi, je courais.","La lenteur n’est pas un retard : c’est une loupe.","Alors si on vous demande de ralentir, ne vous excusez pas. Répondez simplement : « je regarde. »"]},{"t":"Élégance","x":["L’élégance, ce n’est pas le luxe : c’est l’absence de bruit inutile.","Un homme a un jour traversé un hall bondé en portant un plateau de verres sans en renverser un seul. Personne n’a applaudi, personne n’a rien remarqué.","C’est précisément ça : l’élégance, c’est quand l’effort disparaît derrière le geste.","Dans mon travail, je cherche la même chose : une phrase si simple qu’on oublie le temps qu’il a fallu pour l’écrire."]},{"t":"Risque","x":["Le risque, c’est la distance entre ce qu’on veut et ce qu’on a déjà.","La première fois que j’ai parlé devant cinquante personnes, j’avais peur de bégayer, de rougir, de disparaître.","J’ai bégayé deux fois, rougi une fois, et je n’ai disparu nulle part.","Voilà ce que le risque m’a appris : on le surévalue avant, on le sous-estime après.","Maintenant je me demande plutôt : et si le vrai risque, c’était de rester à l’abri ?"]},{"t":"Mémoire","x":["La mémoire n’est pas une photo : c’est une recette qu’on réécrit à chaque fois qu’on la cuisine.","Je me souviens de l’odeur de la cuisine de mon enfance, mais plus des murs. Le souvenir a gardé le plus tendre et laissé le reste.","Peut-être est-ce une bonne nouvelle : on garde ce qui nous a nourris.","Alors quand je raconte un souvenir, j’essaie de ne pas dire seulement ce qui s’est passé, mais ce qui est resté."]},{"t":"Silence","x":["Le silence n’est pas l’absence de parole : c’est la parole qui écoute.","Dans une réunion, un collègue s’est tu pendant dix secondes avant de répondre. Dix secondes, c’est un siècle. Tout le monde a retenu son souffle.","Et sa réponse, la seule de la matinée, a changé la décision.","Depuis, je ne cherche plus à remplir les blancs : je les prépare.","Parce qu’un silence bien placé est la phrase la plus courte de la langue."]}],"qr":[{"t":"« Pourquoi avez-vous choisi ce projet ? »","x":["Vous me demandez pourquoi j’ai choisi ce projet.","La réponse tient en une raison : j’y ai vu un problème que je rencontrais moi-même.","Chaque semaine, je perdais deux heures à faire à la main ce qu’un outil simple peut faire en dix minutes.","J’ai donc construit cet outil, d’abord pour moi, puis pour d’autres.","En un mot : j’ai choisi ce projet parce qu’il me faisait gagner du temps, et qu’il peut en faire gagner à d’autres."]},{"t":"« Qu’est-ce qui vous distingue des autres candidats ? »","x":["Vous me demandez ce qui me distingue des autres candidats.","Je ne peux pas parler à leur place, mais je peux dire ce que je fais bien : je livre.","Sur mon dernier projet, j’ai tenu le calendrier, alors que la moitié de l’équipe doutait.","Cette régularité, je la cultive depuis des années : un petit pas par jour plutôt qu’un grand soir.","Donc ce qui me distingue, c’est la constance, et je peux vous le prouver sur pièces."]},{"t":"« Pourquoi cette augmentation maintenant ? »","x":["Vous demandez pourquoi cette demande arrive maintenant.","Parce que le contexte a changé : depuis janvier, j’assure en plus la formation des nouveaux arrivants.","Concrètement, j’ai formé six personnes, et leur délai de prise de poste est passé de six à trois semaines.","C’est un gain mesurable pour l’équipe, et c’est un travail que personne ne m’avait demandé au départ.","C’est pour cela que je vous propose d’en parler maintenant, tant que les résultats sont frais."]},{"t":"« Que feriez-vous avec un budget doublé ? »","x":["Vous me demandez ce que je ferais avec un budget doublé.","Je commencerais par sécuriser ce qui marche : deux postes qui portent déjà les résultats.","Ensuite, j’investirais dans un test à petite échelle, avec un critère d’arrêt clair après trois mois.","Je ne promets pas de tout réussir, je promets de mesurer.","Résumé : d’abord consolider, ensuite expérimenter, et toujours rendre des comptes."]},{"t":"« N’est-ce pas trop risqué ? »","x":["Vous demandez si ce choix n’est pas trop risqué.","Oui, il y a un risque, et je préfère le nommer : si le fournisseur retarde, nous perdons deux semaines.","C’est pourquoi j’ai prévu un deuxième fournisseur, déjà contacté, qui peut livrer en cinq jours.","Le risque existe, mais il est borné.","Donc je maintiens ma recommandation, avec ce plan de secours."]},{"t":"« Pourquoi ne pas simplement baisser le prix ? »","x":["Vous demandez pourquoi ne pas simplement baisser le prix.","Parce que le prix ne dit pas seulement combien, il dit aussi quoi : un prix bas attire des clients qui comparent, un prix juste attire des clients qui restent.","Chez nous, 70 % des clients reviennent, justement parce que nous n’avons jamais cédé sur la qualité.","Baisser le prix aujourd’hui serait gagner un client et en perdre trois.","Je préfère donc ajouter de la valeur plutôt que retirer du prix."]},{"t":"« Comment gérez-vous un désaccord dans l’équipe ? »","x":["Vous me demandez comment je gère un désaccord.","Je commence par une règle : chacun reformule la position de l’autre avant de défendre la sienne.","Dans ma dernière équipe, cette règle a transformé une dispute de vingt minutes en une décision de cinq.","Pourquoi ? Parce qu’on se sent écouté avant d’être contredit.","Bref : reformuler d’abord, décider ensuite."]},{"t":"« Quel est votre plus grand défaut ? »","x":["Vous me demandez mon plus grand défaut.","Je veux en faire trop vite : j’aime avancer, et je saute parfois l’étape de relecture.","Cela m’a coûté une erreur de chiffre dans un rapport, que j’ai corrigée le jour même.","Depuis, je me suis imposé une règle : une relecture à froid, vingt minutes après l’écriture.","Un défaut reconnu, c’est déjà un défaut à moitié réglé."]},{"t":"« Pourquoi quitter votre poste actuel ? »","x":["Vous me demandez pourquoi je quitte mon poste actuel.","Je ne le quitte pas par fuite, je le quitte par envie d’élargir : j’ai appris ce que ce poste pouvait m’apprendre.","J’y ai tenu un budget, formé deux personnes et livré trois projets.","Je cherche maintenant un endroit où ces acquis servent à plus grand.","C’est pour cela que votre offre m’intéresse."]},{"t":"« Qu’attendez-vous de nous ? »","x":["Vous me demandez ce que j’attends de vous.","Trois choses simples : des objectifs clairs, un retour régulier, et la possibilité de prendre des responsabilités quand je les mérite.","En échange, je m’engage à livrer, à demander de l’aide tôt, et à ne pas attendre qu’on me relance.","C’est un échange, pas une faveur.","En résumé : de la clarté de votre côté, de la fiabilité du mien."]}],"argumenter":[{"t":"Il faut échouer pour apprendre","x":["Point : on apprend plus vite en échouant qu’en réussissant du premier coup.","Raison : un échec montre exactement où l’on s’est trompé, alors qu’une réussite cache ses points faibles.","Exemple : à mon premier exposé, j’ai lu mes notes sans lever la tête et la salle a décroché ; au second, j’ai regardé trois personnes et la salle m’a suivi.","Point : donc il faut accepter d’échouer tôt, pour réussir tard."]},{"t":"Le téléphone devrait être interdit en réunion","x":["Point : le téléphone devrait rester dans la poche pendant une réunion.","Raison : il fragmente l’attention de celui qui le consulte, mais aussi de ceux qui le voient faire.","Exemple : dans une réunion de douze personnes, j’ai compté quatre regards qui tombaient vers l’écran à chaque notification, et la question posée a dû être répétée deux fois.","Point : une heure sans téléphone, c’est une réunion plus courte."]},{"t":"Un bon leader sait écouter avant de parler","x":["Point : un bon leader écoute avant de parler.","Raison : celui qui parle en premier ferme la discussion, celui qui écoute l’ouvre.","Exemple : mon ancienne cheffe posait toujours trois questions avant de donner son avis, et ses décisions étaient rarement contestées.","Point : écouter n’est pas une faiblesse du pouvoir, c’est son meilleur outil."]},{"t":"Les études ne suffisent plus","x":["Point : un diplôme ne suffit plus pour trouver sa place.","Raison : les recruteurs demandent aujourd’hui des preuves concrètes de ce qu’on sait faire.","Exemple : deux candidats avec le même diplôme, l’un avait construit un petit site pour une association, l’autre rien : le premier a été rappelé le lendemain.","Point : le diplôme ouvre la porte, les réalisations décident de qui entre."]},{"t":"Travailler à distance rend meilleur","x":["Point : le travail à distance peut rendre meilleur, à condition de s’organiser.","Raison : il oblige à écrire clairement, à planifier et à rendre compte, trois qualités qu’on néglige au bureau.","Exemple : après six mois à distance, mes comptes rendus sont deux fois plus courts et deux fois mieux lus.","Point : le télétravail n’est pas un confort, c’est un entraînement."]},{"t":"Il faut dire non plus souvent","x":["Point : dire non est une compétence professionnelle.","Raison : chaque oui à une demande secondaire est un non à une priorité.","Exemple : j’ai refusé trois réunions non essentielles en un mois, et j’ai livré mon projet principal une semaine plus tôt.","Point : un non clair vaut mieux qu’un oui épuisé."]},{"t":"Lire à voix haute fait progresser","x":["Point : lire à voix haute fait progresser plus vite que lire en silence.","Raison : la voix oblige à ralentir, à découper, à entendre ses erreurs.","Exemple : pendant un mois, j’ai lu dix minutes à voix haute chaque matin, et mes « euh » ont diminué de moitié.","Point : pour parler mieux, il faut d’abord s’entendre."]},{"t":"Le luxe est un art avant d’être un commerce","x":["Point : le luxe est d’abord un art du détail.","Raison : ce qu’on achète, ce n’est pas seulement un objet, c’est des heures de savoir-faire.","Exemple : une maroquinerie artisanale peut passer quarante heures sur un seul sac, jusqu’au fil de la couture.","Point : le prix ne fait pas le luxe, c’est le soin."]},{"t":"Madagascar a un atout sous-estimé","x":["Point : Madagascar a un atout sous-estimé : sa jeunesse.","Raison : une population jeune, c’est une énergie, un marché et des talents à former.","Exemple : à Antananarivo, de jeunes développeurs construisent déjà des applications pour des commerçants locaux avec peu de moyens.","Point : si l’on investit dans cette jeunesse, l’atout devient une force."]},{"t":"Un bon exemple vaut mieux qu’un long discours","x":["Point : un bon exemple convainc plus qu’un long discours.","Raison : on retient une histoire, on oublie une liste.","Exemple : pour expliquer l’épargne, j’ai raconté le prix d’un café par jour sur un an, et trois personnes ont ouvert un compte le soir même.","Point : avant de démontrer, montrez."]}],"connecteurs":[{"t":"Parler du prix","x":["Je voudrais dire une chose sur le prix.","Attention, je ne dis pas qu’il est bas.","Certes, il est plus élevé que la moyenne, mais il comprend trois mois de suivi.","Prenons le cas d’une cliente qui a posé dix questions la première semaine : elle a eu dix réponses.","Autrement dit, vous payez aussi les réponses."]},{"t":"Défendre un changement d’horaire","x":["Je voudrais dire une chose sur les horaires.","Attention, je ne dis pas que l’ancien rythme était mauvais.","Certes, il avait ses habitudes, mais il nous faisait perdre la fin de matinée.","Prenons le cas de la dernière réunion : elle a commencé à dix heures et demie, faute de quorum.","Autrement dit, décaler d’une heure, c’est gagner une matinée."]},{"t":"Défendre l’écoute","x":["Je voudrais dire une chose sur l’écoute.","Attention, je ne dis pas qu’il faut se taire.","Certes, parler fait avancer, mais écouter évite de reculer.","Prenons le cas d’un client qui répète trois fois la même demande : on la lui a mal entendue deux fois.","Autrement dit, écouter, c’est économiser des réunions."]},{"t":"Soutenir un projet","x":["Je voudrais dire une chose sur ce projet.","Attention, je ne dis pas qu’il est sans risque.","Certes, il demande un effort, mais il règle un problème que nous avons depuis deux ans.","Prenons le cas de l’an dernier : nous avons perdu douze jours de travail à cause du même incident.","Autrement dit, ce projet n’est pas un coût, c’est une assurance."]},{"t":"Parler de la peur de se tromper","x":["Je voudrais dire une chose sur les erreurs.","Attention, je ne dis pas qu’il faut en faire exprès.","Certes, personne n’aime se tromper, mais personne n’apprend sans.","Prenons le cas d’un enfant qui apprend à marcher : il tombe, se relève, tombe moins.","Autrement dit, l’erreur n’est pas l’opposé de l’apprentissage, c’en est le chemin."]},{"t":"Défendre un délai","x":["Je voudrais dire une chose sur le délai.","Attention, je ne dis pas que nous sommes en retard.","Certes, le calendrier est serré, mais il est tenable si nous coupons deux options.","Prenons le cas du lot A : il est prêt et validé, il peut partir lundi.","Autrement dit, livrons l’essentiel à l’heure, le reste suivra."]},{"t":"Soutenir une collègue","x":["Je voudrais dire une chose sur Camille.","Attention, je ne dis pas qu’elle n’a jamais de retard.","Certes, elle arrive parfois en dernière minute, mais elle livre toujours.","Prenons le cas du dossier Lambert : tout le monde doutait, elle l’a bouclé en deux jours.","Autrement dit, jugez-la sur ce qu’elle rend, pas sur l’heure à laquelle elle le rend."]},{"t":"Défendre la lecture à voix haute","x":["Je voudrais dire une chose sur la lecture à voix haute.","Attention, je ne dis pas qu’elle remplace la lecture silencieuse.","Certes, lire dans sa tête est plus rapide, mais lire à voix haute est plus exact.","Prenons le cas d’un texte de trois paragraphes : en le lisant à voix haute, on trouve les phrases trop longues.","Autrement dit, la voix est un correcteur."]},{"t":"Parler du télétravail","x":["Je voudrais dire une chose sur le télétravail.","Attention, je ne dis pas qu’il convient à tout le monde.","Certes, il isole parfois, mais il redonne du temps de transport.","Prenons le cas d’un salarié qui perd deux heures par jour dans les trains : sur un an, cela fait presque deux mois.","Autrement dit, la vraie question n’est pas où l’on travaille, mais combien de temps on récupère."]},{"t":"Parler de l’argent","x":["Je voudrais dire une chose sur l’argent.","Attention, je ne dis pas qu’il fait le bonheur.","Certes, il ne remplace ni l’amitié ni la santé, mais il achète du temps.","Prenons le cas d’une famille qui doit réparer son toit : sans épargne, elle s’endette.","Autrement dit, épargner, c’est acheter de la tranquillité à l’avance."]}],"recit":[{"t":"Premier jour de stage, trente minutes de retard","x":["Situation : lundi matin, premier jour de stage, j’arrive avec trente minutes de retard.","Obstacle : la porte est fermée, toute l’équipe est déjà en réunion, et je n’ai ni badge ni numéro.","Action : je frappe, j’entre, je dis « Je suis en retard, je m’excuse, je suis Stephen », et je demande une chaise.","Leçon : une excuse courte suivie d’une action vaut mieux qu’une explication longue."]},{"t":"La panne de micro","x":["Situation : j’allais présenter devant soixante personnes, le micro est tombé en panne à cinq minutes de mon tour.","Obstacle : la salle était grande, et ma voix ne portait pas encore.","Action : j’ai avancé d’un pas, j’ai respiré, et j’ai dit « Si vous m’entendez, levez la main ». Toutes les mains se sont levées.","Leçon : quand l’outil lâche, la voix reste, et demander à la salle la rend complice."]},{"t":"Le train raté","x":["Situation : un jeudi matin, je rate le train pour un entretien important.","Obstacle : le suivant arrive vingt minutes après l’heure du rendez-vous, et je n’ai pas de numéro à appeler.","Action : j’ai écrit un message court à l’adresse du recruteur : « Je serai en retard de vingt minutes, je comprends si vous préférez reporter. »","Leçon : prévenir tôt, brièvement, c’est déjà montrer qu’on est fiable."]},{"t":"Mon premier client","x":["Situation : un restaurateur m’a demandé un devis pour un site.","Obstacle : je n’avais aucun prix de référence, et j’ai eu peur de demander trop.","Action : j’ai calculé mes heures, ajouté une marge, et dit mon prix sans trembler, puis je me suis tu.","Leçon : le prix se dit une fois, simplement, et le silence fait le reste."]},{"t":"L’exposé oublié","x":["Situation : un matin, je découvre que l’exposé est pour aujourd’hui, pas pour la semaine prochaine.","Obstacle : aucune diapositive, aucune note, dix minutes devant moi.","Action : j’ai écrit trois mots au tableau, j’ai raconté une histoire qui les reliait, et j’ai terminé par une question à la classe.","Leçon : une idée claire et trois mots valent mieux qu’un plan oublié."]},{"t":"Le client mécontent","x":["Situation : un client m’appelle, furieux, parce qu’une livraison est en retard.","Obstacle : il parle fort et ne me laisse pas répondre.","Action : j’ai attendu qu’il termine, j’ai reformulé son problème en une phrase, puis proposé une solution et une date.","Leçon : on désamorce une colère en montrant qu’on l’a comprise."]},{"t":"La première prise de parole","x":["Situation : à dix-sept ans, on me demande de présenter l’association devant l’école.","Obstacle : mes mains tremblaient, ma voix avait disparu.","Action : j’ai commencé par une phrase préparée, j’ai regardé un camarade au fond, et j’ai continué.","Leçon : la première phrase préparée, c’est le garde-fou de toutes les autres."]},{"t":"Le dossier perdu","x":["Situation : l’ordinateur plante, trois heures avant un rendu, et le dossier n’est pas sauvegardé.","Obstacle : le temps manque et la panique monte.","Action : j’ai éteint l’écran, repris une feuille, noté les trois idées principales, puis reconstruit le dossier plus court.","Leçon : le dossier perdu m’a appris à sauvegarder, et à aller à l’essentiel."]},{"t":"La question piège","x":["Situation : lors d’une soutenance, un membre du jury me pose une question hors sujet.","Obstacle : je n’avais pas la réponse.","Action : j’ai dit « Je n’ai pas cette information, je vous la transmets demain », puis j’ai noté la question.","Leçon : avouer simplement ce qu’on ignore vaut mieux que bluffer."]},{"t":"Le dimanche du filet","x":["Situation : enfant, je tenais un bout du filet de pêche de mon grand-père chaque dimanche matin.","Obstacle : je m’ennuyais, et il ne parlait presque jamais.","Action : un jour, j’ai arrêté de regarder mes pieds et j’ai regardé ses mains.","Leçon : on apprend souvent en silence, à côté de quelqu’un qui travaille."]}],"discours":[{"t":"Pourquoi lire à voix haute","x":["[Ouverture] Imaginez qu’on vous tende un livre et qu’on vous dise : lisez-le comme si quelqu’un vous écoutait.","[Plan] Je vais vous dire trois choses : pourquoi la voix aide, comment s’y mettre, et quoi faire dès demain.","[1] D’abord, la voix ralentit. On ne peut pas lire vite à voix haute sans trébucher, donc on lit juste.","[2] Ensuite, la voix révèle. On entend les phrases trop longues, celles qui essoufflent.","[3] Enfin, la voix rassure. Plus on lit fort, moins on a peur de parler.","[Appel] Demain, dix minutes, un livre, une voix. Commencez par une page, et écoutez-vous."]},{"t":"Prendre une petite décision","x":["[Ouverture] On ne change pas de vie en un jour, mais on peut changer de matin.","[Plan] Trois idées : une décision, un rituel, un témoin.","[1] La décision : choisissez une chose minuscule, par exemple vous lever dix minutes plus tôt.","[2] Le rituel : faites-la toujours au même endroit, au même moment, pour que le corps l’apprenne.","[3] Le témoin : dites-la à quelqu’un, pour qu’elle devienne une promesse.","[Appel] Choisissez, ce soir, votre dix minutes, et dites-le à une personne."]},{"t":"Savoir remercier","x":["[Ouverture] Un merci bien dit pèse plus lourd qu’un cadeau mal choisi.","[Plan] Trois gestes : regarder, préciser, laisser un silence.","[1] Regarder : un merci adressé à l’écran n’arrive à personne.","[2] Préciser : « merci pour ton aide » est faible, « merci d’avoir relu mon dossier mardi soir » est fort.","[3] Laisser un silence : le merci a besoin d’une seconde pour arriver.","[Appel] Aujourd’hui, remerciez quelqu’un avec un détail précis."]},{"t":"L’art de bien commencer","x":["[Ouverture] La première phrase d’un discours décide de la deuxième.","[Plan] Trois façons de commencer : une image, une question, un chiffre.","[1] L’image : racontez un détail de la salle, et le public se sent présent.","[2] La question : posez-la, puis taisez-vous deux secondes.","[3] Le chiffre : un seul, et surprenant, expliqué tout de suite.","[Appel] Pour votre prochaine prise de parole, écrivez trois ouvertures et gardez la plus courte."]},{"t":"Se préparer sans se figer","x":["[Ouverture] Préparer, ce n’est pas apprendre par cœur, c’est savoir où l’on va.","[Plan] Trois repères : l’idée, les mots-clés, la sortie.","[1] L’idée : une phrase qui résume ce que vous voulez que le public retienne.","[2] Les mots-clés : cinq mots sur une carte, pas plus.","[3] La sortie : la dernière phrase, écrite mot pour mot.","[Appel] Cette semaine, préparez un exposé avec cinq mots-clés et une dernière phrase."]},{"t":"Oser demander de l’aide","x":["[Ouverture] Demander de l’aide n’est pas avouer qu’on ne sait pas, c’est choisir d’aller plus loin.","[Plan] Trois conseils : demander tôt, demander précis, remercier.","[1] Tôt : une question posée au début coûte dix minutes, posée à la fin elle en coûte dix heures.","[2] Précis : « peux-tu me montrer comment faire ça ? » vaut mieux que « je n’y arrive pas ».","[3] Remercier : on aide plus volontiers quelqu’un qui dit merci.","[Appel] Aujourd’hui, posez la question que vous retardez depuis une semaine."]},{"t":"Gérer un échec","x":["[Ouverture] Tout le monde a raté quelque chose, peu de gens savent en parler.","[Plan] Trois étapes : nommer, comprendre, repartir.","[1] Nommer : dire simplement ce qui n’a pas marché, sans adjectif.","[2] Comprendre : chercher une cause, pas un coupable.","[3] Repartir : choisir un petit pas, et le faire dans la journée.","[Appel] Pensez à un échec récent, et écrivez la première étape en une phrase."]},{"t":"Réussir un entretien","x":["[Ouverture] Un entretien, c’est une conversation avec un enjeu.","[Plan] Trois clés : préparer trois histoires, poser deux questions, remercier à la fin.","[1] Trois histoires vraies, qui montrent ce que vous savez faire.","[2] Deux questions sur le poste, pour montrer que vous réfléchissez déjà à l’après.","[3] Un merci précis, envoyé le soir même.","[Appel] Écrivez dès ce soir vos trois histoires, une ligne chacune."]},{"t":"Pourquoi s’entraîner","x":["[Ouverture] Personne n’est né orateur, tous les orateurs se sont entraînés.","[Plan] Trois raisons : la répétition, le retour, le plaisir.","[1] La répétition : dire une phrase vingt fois la rend naturelle.","[2] Le retour : s’enregistrer montre ce qu’on ne sent pas.","[3] Le plaisir : on aime ce qu’on réussit.","[Appel] Ce soir, enregistrez-vous trente secondes et écoutez."]},{"t":"Bien finir","x":["[Ouverture] On se souvient de la dernière phrase plus que de la première.","[Plan] Trois façons de finir : une promesse, une image, une demande.","[1] Une promesse : dire ce qu’on fera.","[2] Une image : boucler sur l’ouverture.","[3] Une demande : dire ce qu’on attend du public.","[Appel] Écrivez la fin de votre prochain discours en premier, et construisez le reste ensuite."]}],"debat":[{"t":"POUR : le télétravail comme droit","x":["Thèse : le télétravail devrait être un droit.","Argument un : il rend des heures de transport à ceux qui en perdent deux par jour.","Argument deux : il ouvre l’emploi à ceux qui vivent loin des grandes villes.","Réfutation : on dit qu’on perd le lien d’équipe ; le lien se construit par des jours de présence choisis, pas subis.","Conclusion : un droit encadré, pas une obligation."]},{"t":"CONTRE : la semaine de quatre jours","x":["Thèse : la semaine de quatre jours n’est pas la bonne réponse partout.","Argument un : dans les métiers de service, quatre jours plus longs fatiguent plus qu’ils ne reposent.","Argument deux : tous les secteurs ne peuvent pas fermer un jour de plus sans perdre des clients.","Réfutation : on cite des essais réussis ; ils concernent surtout des bureaux, pas des hôpitaux ni des commerces.","Conclusion : oui à l’expérience, non à la règle unique."]},{"t":"POUR : l’IA dans la création artistique","x":["Thèse : l’intelligence artificielle devrait être autorisée dans la création.","Argument un : elle est un outil, comme l’appareil photo l’a été pour la peinture.","Argument deux : elle permet à ceux qui n’ont pas le matériel de créer.","Réfutation : on craint le vol d’œuvres ; la solution est la transparence et la rémunération, pas l’interdiction.","Conclusion : un outil permis, des règles claires."]},{"t":"CONTRE : les réseaux avant quinze ans","x":["Thèse : les réseaux sociaux ne devraient pas être ouverts avant quinze ans.","Argument un : les algorithmes exploitent l’attention d’un cerveau qui se forme.","Argument deux : le harcèlement en ligne suit l’enfant jusque dans sa chambre.","Réfutation : on dit que les jeunes s’en passeront difficilement ; ils se passent déjà de bien des choses utiles.","Conclusion : un âge minimum, comme pour le permis."]},{"t":"POUR : le vote obligatoire","x":["Thèse : voter devrait être obligatoire.","Argument un : un scrutin élu par quarante pour cent des électeurs est un scrutin faible.","Argument deux : l’obligation pousse les partis à parler à tous, pas seulement aux convaincus.","Réfutation : on invoque la liberté ; on est déjà obligé de payer l’impôt et d’aller à l’école.","Conclusion : un devoir léger pour une démocratie plus solide."]},{"t":"CONTRE : l’uniforme à l’école","x":["Thèse : l’uniforme obligatoire n’est pas la solution.","Argument un : il règle l’apparence sans régler les inégalités.","Argument deux : il coûte aux familles, et ces coûts sont rarement pris en charge.","Réfutation : on dit qu’il supprime les comparaisons ; elles se déplacent vers les chaussures ou le téléphone.","Conclusion : mieux vaut éduquer au respect que cacher les différences."]},{"t":"POUR : publier les prix de fabrication du luxe","x":["Thèse : les marques de luxe devraient publier leurs coûts de fabrication.","Argument un : la transparence justifie le prix par le savoir-faire.","Argument deux : elle protège le client contre l’illusion de rareté.","Réfutation : on dit que le luxe vit du secret ; une marque solide n’a rien à craindre du détail.","Conclusion : la confiance coûte moins cher que le mystère."]},{"t":"CONTRE : l’interdiction du téléphone au collège","x":["Thèse : interdire le téléphone au collège ne suffit pas.","Argument un : il faut aussi apprendre à s’en servir, pas seulement à s’en passer.","Argument deux : l’interdiction se contourne, l’éducation reste.","Réfutation : on invoque la concentration ; elle s’obtient aussi avec des règles d’usage claires.","Conclusion : poser un cadre et former, plutôt qu’interdire seulement."]},{"t":"POUR : une année de service civique","x":["Thèse : une année de service civique devrait être proposée à tous les jeunes.","Argument un : elle brasse des profils qui ne se croisent jamais.","Argument deux : elle donne une première expérience concrète.","Réfutation : on craint le coût ; un jeune formé et engagé coûte moins cher que dix ans d’indifférence.","Conclusion : une année pour mieux se connaître, et connaître les autres."]},{"t":"CONTRE : la note unique à l’école","x":["Thèse : la note unique ne dit pas ce qu’un élève sait faire.","Argument un : une moyenne mélange des compétences très différentes.","Argument deux : elle décourage ceux qui progressent sans atteindre le seuil.","Réfutation : on dit qu’elle est simple ; la simplicité n’est pas la justesse.","Conclusion : un bilan par compétences, plus lisible et plus juste."]}],"objection":[{"t":"« C’est trop cher »","x":["Objection : « C’est trop cher. »","Concéder : c’est un investissement, et je comprends que vous vouliez être sûr.","Recadrer : la vraie question, c’est ce que ça vous coûte de ne pas le faire.","Preuve : sur trois mois, deux élèves sur trois ont doublé leur temps de parole sans notes.","Conclure : dites-moi quel résultat justifierait ce prix pour vous."]},{"t":"« Je dois réfléchir »","x":["Objection : « Je dois réfléchir. »","Concéder : bien sûr, c’est une bonne décision à prendre sans précipitation.","Recadrer : sur quoi voulez-vous réfléchir, précisément : le prix, le moment, ou le contenu ?","Preuve : en général, quand un point est clair, la décision se prend dans la journée.","Conclure : dites-moi ce qui manque, et je vous l’apporte avant demain."]},{"t":"« Je peux le faire seul »","x":["Objection : « Je peux le faire seul. »","Concéder : c’est vrai, beaucoup de choses se font seul.","Recadrer : la question est de savoir en combien de temps et avec quelle assurance.","Preuve : ceux que j’accompagne gagnent en moyenne trois mois sur leur projet.","Conclure : voulez-vous gagner ces trois mois ?"]},{"t":"« Mon cousin le fait gratuitement »","x":["Objection : « Mon cousin le fait gratuitement. »","Concéder : c’est une belle solution, et la famille est précieuse.","Recadrer : gratuit ne veut pas dire sans coût : délais, disponibilité, garantie.","Preuve : sur mes derniers projets, les délais ont été tenus à cent pour cent, avec un contrat.","Conclure : qu’est-ce qui compte le plus pour vous : le prix ou la certitude ?"]},{"t":"« Ce n’est pas le bon moment »","x":["Objection : « Ce n’est pas le bon moment. »","Concéder : le moment compte, je suis d’accord.","Recadrer : qu’est-ce qui rendrait le moment bon ?","Preuve : la plupart de mes clients disent attendre un moment idéal qui n’arrive jamais.","Conclure : si on commençait petit, cette semaine, avec une première étape ?"]},{"t":"« Je ne vous connais pas »","x":["Objection : « Je ne vous connais pas. »","Concéder : c’est normal, nous nous rencontrons à peine.","Recadrer : c’est pour cela que je propose un premier échange gratuit, sans engagement.","Preuve : voici trois témoignages de personnes qui ont commencé ainsi.","Conclure : voulez-vous commencer par ce premier pas ?"]},{"t":"« Les résultats sont-ils garantis ? »","x":["Objection : « Les résultats sont-ils garantis ? »","Concéder : non, personne honnête ne peut garantir un résultat.","Recadrer : ce que je garantis, c’est le travail, le suivi et la transparence.","Preuve : voici les chiffres de mes derniers élèves, avec leurs points de départ.","Conclure : êtes-vous prêt à faire votre part ?"]},{"t":"« C’est trop long »","x":["Objection : « C’est trop long. »","Concéder : le temps est une vraie ressource.","Recadrer : ce n’est pas la durée qui compte, mais l’effort par jour.","Preuve : dix minutes par jour suffisent, comme le montrent mes élèves les plus réguliers.","Conclure : quel créneau de dix minutes pouvez-vous tenir ?"]},{"t":"« Je n’ai pas le budget »","x":["Objection : « Je n’ai pas le budget. »","Concéder : je comprends, le budget est une contrainte réelle.","Recadrer : regardons ce que vous pouvez engager, et ce que ça rapporte.","Preuve : un module à bas prix existe, et je propose aussi un paiement en trois fois.","Conclure : quelle option vous semble tenable ?"]},{"t":"« Je vais comparer »","x":["Objection : « Je vais comparer avec d’autres. »","Concéder : comparer est une bonne idée.","Recadrer : voici les trois critères à regarder : le suivi, les preuves, la clarté du prix.","Preuve : je vous donne mes chiffres, comparez les leurs.","Conclure : revenez vers moi demain, avec vos questions."]}],"reprise":[{"t":"Coupé en réunion","x":["Situation : on vous coupe au milieu de votre phrase.","Phrase-pont : « Je voudrais terminer mon raisonnement, il me reste deux points. »","Numéroter : « Premièrement, le coût ; deuxièmement, le délai. »","Finir : « Voilà pourquoi je propose de commencer par le délai. »"]},{"t":"Interrompu par un collègue","x":["Situation : un collègue prend la parole avant que vous ayez fini.","Phrase-pont : « Une seconde, je termine et je te laisse. »","Numéroter : « Je disais trois choses : la date, le budget, le responsable. »","Finir : « C’est le responsable qui manque. À toi. »"]},{"t":"Coupé par un client","x":["Situation : un client vous coupe pour poser une autre question.","Phrase-pont : « Excellente question, je la prends juste après avoir fini cette idée. »","Numéroter : « Deux éléments importants : le prix, puis la garantie. »","Finir : « Maintenant, votre question. »"]},{"t":"Coupé par la voix de l’enregistrement","x":["Situation : un bruit couvre votre voix quelques secondes.","Phrase-pont : « Je reprends, nous en étions à la deuxième raison. »","Numéroter : « Deuxièmement, le temps gagné. Troisièmement, la fiabilité. »","Finir : « C’est ce qui rend cette solution durable. »"]},{"t":"Face à quelqu’un qui parle plus fort","x":["Situation : votre interlocuteur monte la voix pour couvrir la vôtre.","Phrase-pont : (voix plus basse) « Je vous écoute dès que j’ai terminé. »","Numéroter : « Un : le fait. Deux : la conséquence. »","Finir : « Maintenant, je vous écoute. »"]},{"t":"Pendant un entretien","x":["Situation : le recruteur vous coupe pour passer à la question suivante.","Phrase-pont : « Je termine en une phrase : »","Numéroter : « J’ai géré le budget et formé deux personnes. »","Finir : « Je suis prêt pour la question suivante. »"]},{"t":"Pendant une soutenance","x":["Situation : un membre du jury vous interrompt.","Phrase-pont : « Permettez-moi de conclure ce point, puis je répondrai. »","Numéroter : « Deux résultats : une baisse de coûts, une hausse de satisfaction. »","Finir : « Je réponds à votre question. »"]},{"t":"Au téléphone","x":["Situation : la personne parle en même temps que vous.","Phrase-pont : « Pardon, je termine ma phrase. »","Numéroter : « Je voulais dire deux choses : la date de livraison et le prix. »","Finir : « À vous. »"]},{"t":"En visio","x":["Situation : deux personnes parlent à la fois dans la visio.","Phrase-pont : « Je reprends, si vous le permettez. »","Numéroter : « Premier point : l’objectif. Deuxième point : l’échéance. »","Finir : « Merci, je vous laisse la parole. »"]},{"t":"Face à un proche","x":["Situation : un proche vous coupe sans cesse.","Phrase-pont : « J’aimerais finir, ça compte pour moi. »","Numéroter : « Deux choses : ce que je ressens, ce que je propose. »","Finir : « Dis-moi maintenant ce que tu en penses. »"]}],"interview":[{"t":"Interview : l’association","x":["Q1 chiffre : « Combien de membres ? » — « Quarante-deux membres actifs, dont dix-sept depuis plus d’un an. »","Q2 piège : « N’est-ce pas peu ? » — « C’est modeste, et c’est le chiffre que je peux garantir ; nous visons soixante avant juin. »","Q3 personnelle : « Pourquoi vous ? » — « Parce que j’ai connu le manque de lieu pour s’entraîner à parler. »"]},{"t":"Interview : l’application","x":["Q1 chiffre : « Combien d’utilisateurs ? » — « Cent vingt, dont quarante actifs chaque semaine. »","Q2 piège : « Elle est gratuite, comment gagnez-vous de l’argent ? » — « Aujourd’hui nous ne gagnons pas encore ; l’objectif est d’abord la qualité. »","Q3 personnelle : « Pourquoi vous ? » — « Parce que j’utilise moi-même cet outil tous les jours. »"]},{"t":"Interview : un stage","x":["Q1 chiffre : « Combien de dossiers traitiez-vous ? » — « Environ dix par semaine. »","Q2 piège : « Qu’avez-vous raté ? » — « Une facture envoyée en double ; je l’ai corrigée le jour même et mis en place un contrôle. »","Q3 personnelle : « Pourquoi ce métier ? » — « Parce que j’aime que les choses soient bien rangées pour que d’autres avancent. »"]},{"t":"Interview : un commerce","x":["Q1 chiffre : « Quel chiffre d’affaires ? » — « Je préfère ne pas donner le montant exact, mais il a progressé de vingt pour cent. »","Q2 piège : « Vos concurrents sont moins chers. » — « Oui, et ils ne proposent pas le suivi que nous offrons. »","Q3 personnelle : « Pourquoi vous ? » — « Parce que c’est le métier de ma famille, et que je veux le moderniser. »"]},{"t":"Interview : un projet étudiant","x":["Q1 chiffre : « Quel budget ? » — « Deux mille euros, financés à moitié par l’école. »","Q2 piège : « Est-ce réaliste ? » — « Oui si nous tenons trois jalons ; sinon, nous réduisons le périmètre. »","Q3 personnelle : « Pourquoi ce projet ? » — « Parce que j’ai connu ce problème personnellement. »"]},{"t":"Interview : un changement de poste","x":["Q1 chiffre : « Combien de temps dans l’entreprise ? » — « Deux ans et trois mois. »","Q2 piège : « Vous partez donc fâché ? » — « Non, je pars avec reconnaissance et l’envie d’apprendre ailleurs. »","Q3 personnelle : « Qu’est-ce qui vous motive ? » — « Voir un projet commencé et fini. »"]},{"t":"Interview : un échec","x":["Q1 chiffre : « Combien avez-vous perdu ? » — « Environ trois mille euros. »","Q2 piège : « C’est votre faute ? » — « En partie : j’ai mal estimé la demande. »","Q3 personnelle : « Qu’avez-vous appris ? » — « À tester petit avant de lancer grand. »"]},{"t":"Interview : une réussite","x":["Q1 chiffre : « Quel résultat ? » — « Trente pour cent de clients en plus en six mois. »","Q2 piège : « N’est-ce pas de la chance ? » — « La chance existe, mais nous avons testé sept versions avant d’y arriver. »","Q3 personnelle : « À qui le devez-vous ? » — « À l’équipe, et à un client qui nous a dit la vérité. »"]},{"t":"Interview : un livre","x":["Q1 chiffre : « Combien d’exemplaires ? » — « Trois cents, vendus en direct. »","Q2 piège : « Pourquoi ne pas passer par un éditeur ? » — « Je veux d’abord mesurer l’intérêt réel. »","Q3 personnelle : « Pourquoi écrire ? » — « Parce que je pense mieux avec un stylo. »"]},{"t":"Interview : une prise de parole","x":["Q1 chiffre : « Combien de personnes dans la salle ? » — « Environ soixante. »","Q2 piège : « Avez-vous eu peur ? » — « Oui, et je l’ai dit dès la première phrase. »","Q3 personnelle : « Que retenez-vous ? » — « Qu’on tient mieux quand on assume le trac. »"]}],"aveu":[{"t":"Chiffre inconnu : désabonnement","x":["Question : « Quel est le taux de désabonnement ? »","Aveu : je n’ai pas le chiffre exact avec moi.","Ordre de grandeur : autour d’un abonné sur dix par an, d’après mes derniers relevés.","Échéance : je vous envoie le chiffre vérifié avant vendredi."]},{"t":"Chiffre inconnu : budget","x":["Question : « Quel est le budget total ? »","Aveu : je n’ai pas le montant définitif.","Ordre de grandeur : entre dix et douze mille euros.","Échéance : je vous le confirme lundi, après la réunion de finance."]},{"t":"Détail inconnu : date","x":["Question : « Quelle est la date de livraison ? »","Aveu : je ne peux pas vous donner une date certaine aujourd’hui.","Ordre de grandeur : plutôt dans la deuxième quinzaine de mars.","Échéance : je vous donne une date ferme jeudi."]},{"t":"Détail inconnu : concurrents","x":["Question : « Combien de concurrents sur le marché ? »","Aveu : je n’ai pas de liste complète.","Ordre de grandeur : j’en connais cinq principaux.","Échéance : je vous envoie la liste complète demain matin."]},{"t":"Chiffre inconnu : clients","x":["Question : « Combien de clients avez-vous eus cette année ? »","Aveu : le total exact m’échappe.","Ordre de grandeur : une trentaine.","Échéance : je vérifie dans mes fichiers et vous écris ce soir."]},{"t":"Détail inconnu : règlement","x":["Question : « Cette règle s’applique-t-elle aux étudiants ? »","Aveu : je ne suis pas sûr.","Ordre de grandeur : je crois que oui, mais sous conditions.","Échéance : je vérifie auprès du service concerné et je reviens vers vous demain."]},{"t":"Chiffre inconnu : audience","x":["Question : « Combien de personnes vous suivent ? »","Aveu : je n’ai pas le chiffre à jour.","Ordre de grandeur : environ deux mille.","Échéance : je regarde les statistiques ce soir et vous envoie la capture."]},{"t":"Détail inconnu : prix concurrent","x":["Question : « Combien coûte le concurrent ? »","Aveu : je ne connais pas son tarif précis.","Ordre de grandeur : à peu près vingt pour cent moins cher, mais sans suivi.","Échéance : je compare les offres et je vous envoie le tableau."]},{"t":"Question hors sujet","x":["Question : « Que pensez-vous de l’élection ? »","Aveu : ce n’est pas mon domaine et je n’ai pas d’avis informé.","Ordre de grandeur : je préfère ne pas répondre à la place des spécialistes.","Échéance : revenons à notre sujet, je peux traiter votre question sur le projet."]},{"t":"Chiffre sourcé plus tard","x":["Question : « D’où vient ce chiffre ? »","Aveu : je l’ai retenu d’une lecture, mais je ne retrouve pas la source sur-le-champ.","Ordre de grandeur : il m’a semblé autour de soixante pour cent.","Échéance : je retrouve la source et je vous l’envoie avant ce soir, sinon je retire le chiffre."]}],"virelangue":[{"t":"Le souffle et le sillon","x":["Un souffle sur le sillon, un sillon sous le souffle.","Chaque matin, le semeur sème ses semences sans se lasser.","Les sillons sont sages, les semences sont sûres, et le soleil, lui, sourit.","Sème sans souci, sème sans hâte : ce qui est semé finit par sortir."]},{"t":"La patience du pêcheur","x":["Le pêcheur patient pose sa ligne près du pont.","Pas de prise, pas de panique : la patience prend le temps.","Peu à peu, le poisson pense à mordre.","Et quand il mord, le pêcheur ne perd pas son calme : il prend ce qui est prêt."]},{"t":"Les trois cartes","x":["Trois cartes, trois cris, trois raisons de commencer.","Chaque chose a sa chance, chaque chance a son chemin.","Cherche, choisis, change : ce sont les trois temps du courage.","Alors, sans crainte, commence."]},{"t":"Le bruit du train","x":["Le train traverse la plaine tranquillement, très tôt, très tard.","Tic, tac, tic, tac : le temps tape sur les rails.","Tout le monde attend, tout le monde entend le train.","Et le train, lui, ne ralentit jamais pour les rêveurs."]},{"t":"La voix claire","x":["Ma voix voyage, vive et vraie, vers vous.","Voyelles ouvertes, consonnes nettes : voilà la voie.","Venez, voyez, vérifiez : une voix claire vaut mille voiles.","Et vous, que voulez-vous que votre voix vous dise ?"]},{"t":"Le chant du marchand","x":["Le marchand marche, mesure, marchande et murmure.","Mon marché, mes mots, mes mains : tout est mesuré.","Mieux vaut un mot juste qu’un mot multiplié.","Alors, marchand, mesure tes mots comme tu mesures ton prix."]},{"t":"La rue de la plume","x":["Rue de la plume, plus d’une personne plonge dans sa page.","Plume, papier, pensée : le plaisir est dans le pli du pouce.","Pas à pas, page après page, le poème se pose.","Pense, pose, passe : voilà la plume en paix."]},{"t":"Le grand gardien","x":["Le grand gardien garde les grilles du grand jardin.","Gare au gamin qui glisse, gare au gravier gris.","Le gardien guette, gentil mais ferme.","Au grand jardin, le grand gardien garantit la grâce."]},{"t":"La fleur de la frontière","x":["Fleur de frontière, fragile et fière, fais-toi voir.","Froide au froid, fraîche au feu, fidèle à ta fleur.","Ni la force ni la foule ne font fléchir ta tige.","Fleur, ma frontière, je te regarde fleurir."]},{"t":"Le matin des mots","x":["Matin, marché, moteur : la ville se met en marche.","Mes mots, mes minutes, mes mains font mon matin.","Mieux commencer, c’est déjà moitié mieux finir.","Alors, mesurez vos mots : demain, ils seront des murs ou des ponts."]}],"proverbe":[{"t":"Petit à petit","x":["Proverbe : « Petit à petit, l’oiseau fait son nid. »","Sens : la régularité construit plus que l’élan.","Histoire : ma voisine a écrit une page par jour pendant un an, et elle a un livre.","Morale : ne méprisez pas les petits gestes répétés."]},{"t":"Qui ne tente rien","x":["Proverbe : « Qui ne tente rien n’a rien. »","Sens : sans essai, il n’y a pas de résultat.","Histoire : j’ai envoyé dix candidatures, neuf silences, un oui.","Morale : le oui se cache derrière les silences."]},{"t":"Pierre qui roule","x":["Proverbe : « Pierre qui roule n’amasse pas mousse. »","Sens : changer sans cesse empêche de s’installer.","Histoire : un ami a changé six fois de projet en deux ans, sans finir aucun.","Morale : parfois, il faut rester pour récolter."]},{"t":"L’habit ne fait pas le moine","x":["Proverbe : « L’habit ne fait pas le moine. »","Sens : l’apparence ne dit pas tout.","Histoire : un client en jean m’a signé le plus gros contrat de l’année.","Morale : ne jugez pas avant d’avoir écouté."]},{"t":"Mieux vaut tard que jamais","x":["Proverbe : « Mieux vaut tard que jamais. »","Sens : commencer en retard vaut mieux que ne pas commencer.","Histoire : à vingt-deux ans, j’ai pris ma première leçon de guitare.","Morale : le bon moment, c’est maintenant."]},{"t":"Chat échaudé","x":["Proverbe : « Chat échaudé craint l’eau froide. »","Sens : une mauvaise expérience rend méfiant, même à tort.","Histoire : après une prise de parole ratée, j’ai évité les scènes pendant un an.","Morale : ne laissez pas un seul échec décider de tout."]},{"t":"On n’apprend pas aux vieux singes","x":["Proverbe : « Ce n’est pas à un vieux singe qu’on apprend à faire la grimace. »","Sens : l’expérience est difficile à corriger.","Histoire : mon oncle a refusé d’utiliser un téléphone récent pendant dix ans.","Morale : l’expérience est utile à condition de rester curieux."]},{"t":"Après la pluie","x":["Proverbe : « Après la pluie, le beau temps. »","Sens : les épreuves finissent.","Histoire : après un mauvais trimestre, mon équipe a signé trois clients en un mois.","Morale : tenez, le temps tourne."]},{"t":"Les petits ruisseaux","x":["Proverbe : « Les petits ruisseaux font les grandes rivières. »","Sens : de petites sommes ou de petits efforts s’additionnent.","Histoire : deux mille ariary par jour, au bout d’un an, font un téléphone.","Morale : commencez petit, mais commencez."]},{"t":"Rien ne sert de courir","x":["Proverbe : « Rien ne sert de courir, il faut partir à point. »","Sens : mieux vaut être prêt que pressé.","Histoire : j’ai préparé trois semaines un exposé de dix minutes, et il est passé sans effort.","Morale : la préparation est la vitesse cachée."]}],"arrivee":[{"t":"Entrer dans une salle","x":["Arrivée : je m’arrête à la porte, je respire, je regarde la salle.","Phrase d’entrée : « Bonjour à tous, merci de m’accueillir. »","Silence : deux secondes, regard posé sur trois personnes.","Lancement : « Je vais vous parler de quelque chose de simple. »"]},{"t":"Entrer en réunion","x":["Arrivée : j’entre sans me presser, je salue d’un mot.","Phrase d’entrée : « Bonjour, je suis content d’être là. »","Silence : je pose mon carnet, un temps.","Lancement : « Je commence par l’essentiel. »"]},{"t":"Entrer à un entretien","x":["Arrivée : je sers la main, je regarde dans les yeux.","Phrase d’entrée : « Merci de me recevoir. »","Silence : je m’assois quand on me l’indique.","Lancement : « Je vous raconte en deux minutes mon parcours. »"]},{"t":"Entrer sur scène","x":["Arrivée : je marche lentement jusqu’au centre.","Phrase d’entrée : « Bonsoir. »","Silence : trois secondes, j’attends que la salle se calme.","Lancement : « Une question avant de commencer : »"]},{"t":"Entrer dans un appel","x":["Arrivée : je souris avant de parler.","Phrase d’entrée : « Bonjour, merci de me consacrer ce temps. »","Silence : une seconde pour laisser la personne répondre.","Lancement : « Je vous propose le plan en trois points. »"]},{"t":"Entrer chez un client","x":["Arrivée : j’observe le lieu, je note un détail.","Phrase d’entrée : « Bonjour, j’aime beaucoup votre espace. »","Silence : je laisse le client me guider.","Lancement : « Racontez-moi ce que vous cherchez. »"]},{"t":"Entrer devant des élèves","x":["Arrivée : je pose mes affaires, je regarde la classe.","Phrase d’entrée : « Bonjour, on commence. »","Silence : j’attends le calme sans lever la voix.","Lancement : « Aujourd’hui, un seul objectif. »"]},{"t":"Entrer à un dîner","x":["Arrivée : je souris, je me présente à celui que je ne connais pas.","Phrase d’entrée : « Enchanté, je suis Stephen. »","Silence : j’écoute le nom.","Lancement : « Qu’est-ce qui vous amène ici ? »"]},{"t":"Entrer en visio","x":["Arrivée : caméra à hauteur des yeux, épaules détendues.","Phrase d’entrée : « Bonjour à tous, vous m’entendez bien ? »","Silence : une seconde pour la réponse.","Lancement : « Je partage le plan à l’écran. »"]},{"t":"Entrer après un retard","x":["Arrivée : j’entre discrètement, sans bruit.","Phrase d’entrée : « Désolé du retard. »","Silence : je m’assois sans m’expliquer longuement.","Lancement : « Je me mets à jour, continuez. »"]}],"bascule":[{"t":"De l’émotion au chiffre","x":["Début ému : « Quand j’ai vu ma mère compter les œufs à la main chaque soir, j’ai compris. »","Bascule : « Et ce soir-là, j’ai décidé de chiffrer. »","Fin factuelle : « Résultat : quarante minutes gagnées par jour. »"]},{"t":"De la peur au plan","x":["Début : « J’ai eu peur, une vraie peur. »","Bascule : « Mais la peur donne une liste. »","Fin : « Trois étapes, une par jour, à partir de demain. »"]},{"t":"De l’histoire à la leçon","x":["Début : « Un jour, un client m’a rappelé trois fois pour la même chose. »","Bascule : « Ce jour-là, j’ai compris. »","Fin : « On répète quand on n’est pas entendu. Alors écoutons. »"]},{"t":"Du problème à la promesse","x":["Début : « Aujourd’hui, beaucoup de gens parlent sans être entendus. »","Bascule : « Et si on changeait ça ? »","Fin : « Je vous promets quatre semaines pour parler avec clarté. »"]},{"t":"Du doute à l’action","x":["Début : « Je me suis longtemps demandé si j’avais le droit de me lancer. »","Bascule : « Puis un matin, j’ai envoyé le premier message. »","Fin : « Faites le vôtre aujourd’hui. »"]},{"t":"De la blague au sérieux","x":["Début : « On m’a dit que j’avais deux défauts : je parle trop vite, et je parle trop. »","Bascule : « Plus sérieusement, »","Fin : « La vitesse est un choix, et on peut le changer. »"]},{"t":"De la nostalgie à l’avenir","x":["Début : « Je me souviens de la cour de mon école. »","Bascule : « Mais je ne suis pas ici pour regarder en arrière. »","Fin : « Je suis ici pour ce qu’on va y construire. »"]},{"t":"Du fait personnel au collectif","x":["Début : « J’ai raté mon premier oral. »","Bascule : « Et je ne suis pas le seul. »","Fin : « Ensemble, on peut apprendre à ne plus rater. »"]},{"t":"Du constat à l’appel","x":["Début : « Chaque année, des idées meurent faute d’être dites. »","Bascule : « Et si la vôtre était la prochaine ? »","Fin : « Dites-la ce soir, à une personne. »"]},{"t":"De la critique à la reconnaissance","x":["Début : « On m’a reproché d’être trop calme. »","Bascule : « Et je les remercie. »","Fin : « Parce que ce calme m’a permis d’écouter. »"]}],"simple":[{"t":"Expliquer un mot","x":["Idée : un mot, une phrase.","« Un budget, c’est une promesse faite à son argent. »","Exemple : « Chaque mois, je décide où il va avant qu’il parte. »","Fin : « Simple, non ? »"]},{"t":"Expliquer un prix","x":["Idée : « Le prix, c’est ce que vous payez, la valeur, c’est ce que vous gardez. »","Exemple : « Un manteau à cent euros, porté dix ans, coûte dix euros par an. »","Fin : « Regardez la durée, pas l’étiquette. »"]},{"t":"Expliquer une méthode","x":["Idée : « Ma méthode : dire, répéter, ajuster. »","Exemple : « Je dis la phrase, je la répète dix fois, je l’ajuste. »","Fin : « Trois verbes, et c’est tout. »"]},{"t":"Expliquer un retard","x":["Idée : « J’ai pris du retard, voici pourquoi. »","Exemple : « Le fournisseur a livré mardi au lieu de lundi. »","Fin : « Nouvelle date : vendredi. »"]},{"t":"Expliquer un métier","x":["Idée : « Mon métier : rendre simple ce qui est compliqué. »","Exemple : « Je transforme dix pages en une page. »","Fin : « C’est tout le travail. »"]},{"t":"Expliquer un objectif","x":["Idée : « Mon objectif : soixante membres avant juin. »","Exemple : « Chaque semaine, j’en invite cinq. »","Fin : « Trois mois, soixante. »"]},{"t":"Expliquer une règle","x":["Idée : « Notre règle : un seul sujet par réunion. »","Exemple : « La dernière réunion a duré vingt minutes au lieu de soixante. »","Fin : « Simple, efficace. »"]},{"t":"Expliquer un choix","x":["Idée : « J’ai choisi l’option B. »","Exemple : « Elle coûte moins cher et se livre plus vite. »","Fin : « C’est la plus raisonnable. »"]},{"t":"Expliquer un échec","x":["Idée : « Nous avons échoué sur un point. »","Exemple : « Le message n’a pas été envoyé à temps. »","Fin : « La prochaine fois, on programme l’envoi. »"]},{"t":"Expliquer une idée neuve","x":["Idée : « Et si on enregistrait chaque réunion ? »","Exemple : « Celui qui est absent peut l’écouter dans le train. »","Fin : « Moins de répétitions, plus de clarté. »"]}],"ouverture":[{"t":"Appel à un restaurateur","x":["Accroche : « Bonjour, je suis Stephen, je crée des menus numériques pour restaurants. »","Raison : « Je vous appelle parce que j’ai vu votre carte sur Instagram, très soignée. »","Question : « Aujourd’hui, comment vos clients découvrent-ils vos plats ? »"]},{"t":"Appel à une école","x":["Accroche : « Bonjour, je m’appelle Stephen, j’anime des ateliers de prise de parole. »","Raison : « Je vous contacte parce que vos élèves présentent des exposés chaque trimestre. »","Question : « Comment les préparez-vous aujourd’hui ? »"]},{"t":"Message à un recruteur","x":["Accroche : « Bonjour, je suis Stephen, étudiant en marketing de luxe. »","Raison : « Votre offre de chef de projet correspond à deux de mes expériences. »","Question : « Auriez-vous quinze minutes cette semaine ? »"]},{"t":"Appel à une boutique","x":["Accroche : « Bonjour, ici Stephen, je développe des outils de gestion pour commerçants. »","Raison : « Je vous appelle car beaucoup de boutiques perdent du temps sur leurs stocks. »","Question : « Comment suivez-vous vos stocks en ce moment ? »"]},{"t":"Rencontre en salon","x":["Accroche : « Bonjour, j’aime votre stand. »","Raison : « Je cherche justement un partenaire pour mon projet. »","Question : « Qu’est-ce qui vous amène ici ? »"]},{"t":"Appel à un ancien contact","x":["Accroche : « Bonjour, c’est Stephen, on s’est rencontrés à la conférence de mars. »","Raison : « Je repense à notre discussion sur les formations. »","Question : « Est-ce toujours un sujet pour vous ? »"]},{"t":"Appel à une association","x":["Accroche : « Bonjour, je m’appelle Stephen, j’ai présidé une association de prise de parole. »","Raison : « Je vous appelle pour proposer un atelier gratuit. »","Question : « Quelles sont vos dates libres ? »"]},{"t":"Message LinkedIn","x":["Accroche : « Bonjour, j’ai lu votre article sur la marque employeur. »","Raison : « Il rejoint mon travail sur le luxe. »","Question : « Puis-je vous poser une question rapide ? »"]},{"t":"Appel à un hôtel","x":["Accroche : « Bonjour, je suis Stephen, étudiant en hospitality management. »","Raison : « Je prépare une étude sur l’accueil. »","Question : « Auriez-vous dix minutes avec votre responsable ? »"]},{"t":"Appel de relance","x":["Accroche : « Bonjour, c’est Stephen, nous avons échangé mardi. »","Raison : « Je reviens avec le chiffre promis. »","Question : « Avez-vous un instant pour le voir ensemble ? »"]}],"ratio":[{"t":"Réunion de dix minutes","x":["Écoute : je laisse parler le client quatre minutes.","Parole : je réponds trois minutes, avec un exemple.","Relance : « Qu’est-ce qui compte le plus pour vous ? »","Ratio visé : 60 % écoute, 40 % parole."]},{"t":"Appel découverte","x":["Écoute : cinq minutes de questions ouvertes.","Parole : deux minutes de reformulation.","Relance : « Si je comprends bien, vous voulez... »","Ratio visé : 70 % écoute."]},{"t":"Entretien","x":["Écoute : je laisse finir chaque question.","Parole : je réponds en une minute trente maximum.","Relance : « Cela répond-il à votre question ? »","Ratio visé : 50/50."]},{"t":"Réunion d’équipe","x":["Écoute : chacun parle deux minutes.","Parole : je synthétise en trente secondes.","Relance : « Qui veut ajouter un point ? »","Ratio visé : 80 % écoute."]},{"t":"Vente en boutique","x":["Écoute : « Que cherchez-vous ? » puis silence.","Parole : une suggestion, une seule.","Relance : « Cela vous plaît-il ? »","Ratio visé : 60 % écoute."]},{"t":"Rendez-vous client","x":["Écoute : je prends des notes sans interrompre.","Parole : deux phrases pour résumer.","Relance : « Ai-je bien compris ? »","Ratio visé : 70 % écoute."]},{"t":"Débat","x":["Écoute : je note les deux arguments adverses.","Parole : je réponds à chacun en vingt secondes.","Relance : « Qu’en pensez-vous ? »","Ratio visé : 50/50."]},{"t":"Coaching","x":["Écoute : trois questions, aucune réponse.","Parole : une phrase de reformulation.","Relance : « Que ferais-tu demain ? »","Ratio visé : 80 % écoute."]},{"t":"Présentation","x":["Écoute : deux questions à la salle.","Parole : cinq minutes de contenu.","Relance : « Des questions ? »","Ratio visé : 40 % écoute, 60 % parole."]},{"t":"Appel de suivi","x":["Écoute : je laisse le client raconter ce qui a changé.","Parole : je propose la suite en trente secondes.","Relance : « Quel est le prochain pas pour vous ? »","Ratio visé : 70 % écoute."]}],"prix":[{"t":"Prix d’une formation","x":["« La formation coûte 150 000 ariary. » Silence de trois secondes.","« Elle comprend quatre semaines, un suivi et un enregistrement. »","« Souhaitez-vous commencer lundi ? »"]},{"t":"Prix d’un site","x":["« Le site est à 600 euros. » Silence.","« Il comprend cinq pages et un mois de maintenance. »","« On commence cette semaine ? »"]},{"t":"Prix d’un accompagnement","x":["« L’accompagnement est à 90 euros la séance. » Silence.","« Trois séances suffisent en général. »","« Quelle date vous convient ? »"]},{"t":"Prix d’une application","x":["« Une application sur mesure, à partir de 1 500 euros. » Silence.","« Elle est livrée en trois semaines. »","« Voulez-vous voir une démonstration ? »"]},{"t":"Prix d’un atelier","x":["« L’atelier est à 40 euros par personne. » Silence.","« Il dure deux heures, avec un support. »","« Combien serez-vous ? »"]},{"t":"Prix d’un cours","x":["« Le cours est à 25 000 ariary la séance. » Silence.","« Il comprend les exercices et un suivi par message. »","« Quand voulez-vous commencer ? »"]},{"t":"Prix d’un pack","x":["« Le pack complet est à 300 euros. » Silence.","« Il inclut les trois modules. »","« Quel module vous intéresse d’abord ? »"]},{"t":"Prix d’une prestation photo","x":["« La séance photo est à 120 euros. » Silence.","« Vous recevez vingt photos retouchées. »","« Quel jour vous convient ? »"]},{"t":"Prix d’un abonnement","x":["« L’abonnement est à 9 euros par mois. » Silence.","« Vous pouvez l’arrêter quand vous voulez. »","« Voulez-vous l’essayer ? »"]},{"t":"Prix d’une consultation","x":["« La consultation est à 60 euros. » Silence.","« Elle dure quarante-cinq minutes, avec un compte rendu écrit. »","« On la planifie ? »"]}],"analogie":[{"t":"Expliquer le budget","x":["Comme un réservoir : on y met de l’essence, on sait combien on a avant de partir.","Sans jauge, on tombe en panne au pire moment.","Donc un budget, c’est la jauge de votre argent."]},{"t":"Expliquer l’épargne","x":["Comme planter un arbre : petite graine aujourd’hui, ombre dans dix ans.","On ne voit rien pendant des mois, puis tout pousse.","L’épargne, c’est un arbre que l’on plante pour soi."]},{"t":"Expliquer une marque","x":["Comme un visage : on la reconnaît de loin et on se fie à son expression.","Si le visage change toute la journée, on ne sait plus à qui parler.","Une marque, c’est un visage qui reste le même."]},{"t":"Expliquer la prise de parole","x":["Comme une randonnée : on prépare, on marche, on respire.","Courir au début épuise avant la montée.","Parler, c’est marcher avec la même cadence."]},{"t":"Expliquer le silence","x":["Comme la ponctuation : sans virgule, la phrase étouffe.","Un silence bien placé laisse l’idée atterrir.","Le silence est la virgule de la voix."]},{"t":"Expliquer un contrat","x":["Comme une carte routière : elle ne conduit pas, mais elle évite de se perdre.","Les deux parties savent où elles vont.","Un contrat, c’est la carte avant le voyage."]},{"t":"Expliquer la confiance","x":["Comme un pont : chaque planche posée la rend plus solide.","Un seul faux pas peut l’ébranler.","La confiance se construit planche par planche."]},{"t":"Expliquer la régularité","x":["Comme une goutte d’eau sur la pierre : faible, mais constante.","Avec le temps, elle creuse.","La régularité fait ce que la force ne peut pas."]},{"t":"Expliquer le feedback","x":["Comme un miroir : on ne se voit pas soi-même.","Un bon retour montre ce qu’on ne peut pas voir.","Le feedback, c’est un miroir qui parle."]},{"t":"Expliquer l’écoute","x":["Comme un jardinier : il observe avant d’arroser.","S’il arrose trop vite, il noie.","Écouter, c’est regarder avant d’agir."]}],"positionnement":[{"t":"Coach de prise de parole","x":["Pour qui : étudiants et jeunes professionnels timides.","Quoi : une méthode simple pour parler sans notes.","Différence : exercices courts, textes prêts à lire, suivi chaque semaine.","Phrase : « J’aide les timides à parler avec clarté, en dix minutes par jour. »"]},{"t":"Créateur d’applications","x":["Pour qui : petits commerçants et entrepreneurs.","Quoi : des outils de gestion sur mesure.","Différence : simples, adaptés, livrés en trois semaines.","Phrase : « Je construis l’outil que votre commerce attend. »"]},{"t":"Spécialiste du luxe","x":["Pour qui : jeunes marques et artisans.","Quoi : une identité de luxe accessible.","Différence : un regard sur le détail et le récit.","Phrase : « Je donne à votre savoir-faire la voix qu’il mérite. »"]},{"t":"Formateur en IA","x":["Pour qui : équipes de petites entreprises.","Quoi : utiliser l’IA de façon sûre et efficace.","Différence : cas concrets, règles de sécurité.","Phrase : « J’apprends aux équipes à gagner du temps sans prendre de risque. »"]},{"t":"Photographe discret","x":["Pour qui : marques et personnes sensibles à l’image.","Quoi : portraits et ambiances sobres.","Différence : un style sobre, pas de pose forcée.","Phrase : « Je photographie ce que vous êtes, pas ce que vous jouez. »"]},{"t":"Formateur d’anglais","x":["Pour qui : élèves et adultes qui bloquent à l’oral.","Quoi : parler anglais avec assurance.","Différence : pratique orale dès la première séance.","Phrase : « Vous parlerez anglais dès la première heure. »"]},{"t":"Chef de projet IT","x":["Pour qui : PME qui lancent un outil numérique.","Quoi : cadrer, planifier et livrer.","Différence : une communication claire.","Phrase : « Je fais en sorte que les projets finissent. »"]},{"t":"Créateur de contenu","x":["Pour qui : marques qui veulent parler vrai.","Quoi : vidéos courtes et textes sobres.","Différence : pas de cliché.","Phrase : « Je donne du sens à votre voix de marque. »"]},{"t":"Conférencier étudiant","x":["Pour qui : écoles et associations.","Quoi : ateliers de prise de parole.","Différence : un pair, pas un expert lointain.","Phrase : « J’ai été à votre place, je sais ce qui bloque. »"]},{"t":"Entrepreneur à Madagascar","x":["Pour qui : jeunes talents malgaches.","Quoi : emplois et outils numériques.","Différence : ancré localement, ambitieux.","Phrase : « Je construis ici ce que le monde attend. »"]}],"story":[{"t":"Le déclic","x":["Avant : je parlais peu, j’évitais les micros.","Déclic : à vingt ans, on m’a demandé de présenter devant l’école.","Pendant : mes mains tremblaient, j’ai commencé par une phrase préparée.","Après : j’ai compris que la voix s’entraîne, comme un muscle."]},{"t":"L’arrivée en France","x":["Avant : je vivais à Madagascar, entouré des miens.","Déclic : une opportunité d’études à Paris.","Pendant : j’ai quitté mon pays avec un sac et un projet.","Après : je construis ici ce que je veux construire là-bas."]},{"t":"Les premiers cours d’anglais","x":["Avant : je parlais anglais en classe, pas en vrai.","Déclic : un ami m’a mis face à un étranger.","Pendant : j’ai bafouillé, il a souri.","Après : j’ai fondé un club pour que d’autres osent."]},{"t":"La première application","x":["Avant : je notais tout sur papier.","Déclic : un budget perdu par oubli.","Pendant : j’ai construit un petit outil en une nuit.","Après : cet outil est devenu une famille d’outils."]},{"t":"L’alternance","x":["Avant : étudiant sans expérience.","Déclic : un entretien où j’ai dit « je veux apprendre ».","Pendant : un an de chef de projet.","Après : une équipe qui m’a fait confiance."]},{"t":"L’association","x":["Avant : une idée entre amis.","Déclic : un premier événement avec dix personnes.","Pendant : on a invité, affiché, recommencé.","Après : une association qui vit sans nous."]},{"t":"La photographie","x":["Avant : je regardais les photos des autres.","Déclic : un téléphone, une rue, une lumière.","Pendant : je cadrais dans l’ombre.","Après : un style discret qui me ressemble."]},{"t":"Le livre","x":["Avant : des notes éparses.","Déclic : un élève m’a demandé « où lire ça ? ».","Pendant : trois mois d’écriture le soir.","Après : un manuel que d’autres utilisent."]},{"t":"Un échec","x":["Avant : j’étais sûr de moi.","Déclic : un projet lancé sans test.","Pendant : trois mois pour rien.","Après : je teste petit avant de lancer grand."]},{"t":"Ma mère et la ferme","x":["Avant : elle comptait les œufs à la main.","Déclic : un soir, elle m’a dit qu’elle perdait le fil.","Pendant : j’ai écrit un logiciel pour elle.","Après : elle gère sa ferme sur téléphone."]}],"pitchsoi":[{"t":"Pitch de 30 secondes","x":["Je m’appelle Stephen, j’ai vingt-trois ans, je viens de Madagascar.","Je crée des outils numériques pour des petits commerces.","Mon dernier projet fait gagner quarante minutes par jour à une ferme.","Je cherche des clients qui perdent du temps, et je leur rends.","Si vous en connaissez un, présentez-nous."]},{"t":"Pitch pour un recruteur","x":["Je suis étudiant en marketing de luxe, et j’ai passé un an en gestion de projet IT.","J’ai livré trois projets dans les délais.","Je veux mettre cette rigueur au service d’une marque.","Je serais heureux de vous en parler plus longuement."]},{"t":"Pitch pour un client","x":["Je construis des applications simples pour des commerces.","Je commence toujours par comprendre votre quotidien.","Je livre en trois semaines, avec formation.","Voulez-vous voir ce que cela donnerait chez vous ?"]},{"t":"Pitch pour une école","x":["J’ai présidé une association de prise de parole pendant un an.","J’ai organisé des ateliers pour plus de cinquante élèves.","Je propose le même format ici, gratuitement.","Quand pouvons-nous nous voir ?"]},{"t":"Pitch pour un partenaire","x":["Je lance une plateforme de prise de parole.","Elle propose des leçons, des exercices et des textes prêts à lire.","Je cherche un partenaire pour la distribuer.","Pouvons-nous en discuter cette semaine ?"]},{"t":"Pitch pour une soirée","x":["Je suis Stephen, je viens d’arriver à Paris.","J’étudie le luxe et je crée des applications.","Ce qui m’anime : aider les gens à parler avec confiance.","Et vous, qu’est-ce qui vous anime ?"]},{"t":"Pitch pour un jury","x":["Mon projet répond à un problème simple : peu de gens apprennent à parler.","Ma solution : une application avec des textes à lire et des exercices.","Mes preuves : trente utilisateurs en test.","Je demande aujourd’hui vos retours."]},{"t":"Pitch pour un étudiant","x":["Je fais des applis pour m’entraîner à parler.","Dix minutes par jour, des textes déjà écrits.","Tu lis, tu t’enregistres, tu t’écoutes.","Essaie, c’est gratuit."]},{"t":"Pitch pour un investisseur","x":["Je construis une famille d’applications pour entrepreneurs malgaches.","Elles sont simples, mobiles, adaptées au réseau local.","Premiers usages : une ferme et un centre d’anglais.","Je cherche un premier soutien pour passer à l’échelle."]},{"t":"Pitch pour LinkedIn","x":["Étudiant, entrepreneur, créateur d’outils numériques.","Je construis des applications utiles aux petits commerces.","Ma conviction : on grandit quand on a le bon environnement.","Je suis ouvert aux échanges sur ces sujets."]}],"contenu":[{"t":"Post : régularité","x":["Accroche : « Dix minutes par jour. »","Idée : la régularité bat l’intensité.","Exemple : un mois de lecture à voix haute, moins de « euh ».","Appel : « Et vous, quelle est votre dix minutes ? »"]},{"t":"Post : première prise de parole","x":["Accroche : « Mes mains tremblaient. »","Idée : on survit au trac.","Exemple : première phrase préparée, regard posé.","Appel : « Racontez-moi la vôtre. »"]},{"t":"Post : le silence","x":["Accroche : « Le silence est une phrase. »","Idée : se taire bien, c’est parler mieux.","Exemple : une réponse après dix secondes.","Appel : « Osez le silence aujourd’hui. »"]},{"t":"Post : une erreur","x":["Accroche : « J’ai perdu trois mois. »","Idée : tester avant de lancer.","Exemple : un projet sans test.","Appel : « Quel test ferez-vous cette semaine ? »"]},{"t":"Post : remercier","x":["Accroche : « Merci n’est pas un mot facile. »","Idée : un merci précis marque.","Exemple : remercier pour un geste daté.","Appel : « Qui allez-vous remercier ? »"]},{"t":"Post : conseil","x":["Accroche : « Un seul conseil. »","Idée : s’enregistrer.","Exemple : trente secondes de voix chaque soir.","Appel : « Essayez ce soir. »"]},{"t":"Post : coulisses","x":["Accroche : « Ce que personne ne voit. »","Idée : le travail derrière le résultat.","Exemple : vingt versions d’une phrase.","Appel : « Que cachent vos résultats ? »"]},{"t":"Post : une citation vécue","x":["Accroche : « On m’a dit : parle moins vite. »","Idée : la vitesse est un choix.","Exemple : une minute à la moitié du débit.","Appel : « Testez-le aujourd’hui. »"]},{"t":"Post : bilan du mois","x":["Accroche : « Ce mois-ci, trois leçons. »","Idée : apprendre à rendre compte.","Exemple : un point chaque vendredi.","Appel : « Quelle est votre leçon ? »"]},{"t":"Post : annonce","x":["Accroche : « Ça y est. »","Idée : un lancement simple.","Exemple : une application, un public, une date.","Appel : « Dites-moi ce que vous en pensez. »"]}],"express":[{"t":"Mon objet préféré","x":["Voici un objet que je garde toujours : mon carnet noir.","Il m’a vu écrire mes premiers discours.","Chaque page est un morceau de moi.","Si je le perds, je perds une partie de mon histoire.","Et vous, quel objet vous accompagne ?"]},{"t":"Un lieu qui m’a marqué","x":["Un lieu m’a marqué : la gare de Lognes, tôt le matin.","On y croise des gens fatigués, mais jamais indifférents.","Chaque jour, j’y réfléchis à ma journée.","Ce lieu m’apprend la patience.","Quel lieu vous apprend quelque chose ?"]},{"t":"Une personne qui m’inspire","x":["Une personne m’inspire : ma mère.","Elle gère une ferme avec cinq fois moins de moyens que d’autres.","Elle ne se plaint pas, elle compte, elle ajuste.","Elle m’a appris la constance.","Qui vous a appris quelque chose sans le dire ?"]},{"t":"Mon plus grand apprentissage","x":["Mon plus grand apprentissage : demander.","Longtemps, j’ai attendu qu’on devine mes besoins.","Un jour, j’ai posé une question simple, et tout a changé.","Demander n’est pas faible, c’est efficace.","Que devriez-vous demander ?"]},{"t":"Ce que je ferais avec un million","x":["Avec un million, je construirais un centre de formation.","Pas un bâtiment spectaculaire, un lieu simple.","On y apprendrait à parler et à créer.","Le reste viendrait par les gens.","Et vous, que feriez-vous ?"]},{"t":"Mon matin idéal","x":["Mon matin idéal commence à cinq heures.","Un verre d’eau, dix minutes de lecture à voix haute.","Puis une marche, sans téléphone.","À huit heures, j’ai déjà vécu une journée.","Quel est le vôtre ?"]},{"t":"Un conseil à mon moi plus jeune","x":["Je dirais à mon moi plus jeune : ose.","Ose parler, ose demander, ose recommencer.","Les erreurs d’aujourd’hui sont les leçons de demain.","Tu auras peur, mais tu iras.","Quel conseil donneriez-vous ?"]},{"t":"Une idée qui me tient à cœur","x":["Une idée me tient à cœur : que chacun sache parler.","Pas pour briller, pour être entendu.","Un mot juste peut changer une vie.","C’est pour cela que je construis tout cela.","Quelle idée vous porte ?"]},{"t":"Ce que j’ai appris cette semaine","x":["Cette semaine, j’ai appris à dire non.","Trois fois, avec un sourire.","Mon agenda a respiré.","Je livre mieux ce que je garde.","Qu’avez-vous appris cette semaine ?"]},{"t":"Un souvenir d’enfance","x":["Un souvenir d’enfance : le dimanche chez ma grand-mère.","L’odeur du riz, le bruit de la casserole.","Personne ne parlait fort, tout le monde se comprenait.","Ce souvenir est ma référence de douceur.","Quel est le vôtre ?"]}],"fetiche":[{"t":"Mon mot fétiche : régulier","x":["Régulier : un mot que j’aime répéter.","Être régulier, c’est tenir quand l’élan s’en va.","Il ne brille pas, il construit.","Chaque matin, c’est mon mot d’ordre.","Et le vôtre ?"]},{"t":"Mon mot fétiche : clair","x":["Clair : un mot qui fait du bien.","Parler clair, c’est respecter celui qui écoute.","Une phrase claire est une phrase qui sert.","Je cherche cette clarté dans tout ce que je dis.","Et vous ?"]},{"t":"Mon mot fétiche : promesse","x":["Promesse : un mot lourd.","Promettre, c’est engager sa parole.","Je promets peu, mais je tiens.","Une promesse tenue vaut dix intentions.","Quelle promesse tenez-vous ?"]},{"t":"Mon mot fétiche : lenteur","x":["Lenteur : un mot qu’on évite.","Pourtant, la lenteur permet de voir.","Je ralentis pour parler juste.","La lenteur est une force discrète.","Et vous, ralentissez-vous ?"]},{"t":"Mon mot fétiche : ensemble","x":["Ensemble : un mot court, un monde large.","Seul, j’avance, ensemble, je construis.","Mon projet n’existe pas sans les autres.","Ensemble, c’est ma façon de grandir.","Avec qui avancez-vous ?"]},{"t":"Mon mot fétiche : question","x":["Question : un mot qui ouvre.","Une bonne question vaut mieux qu’une réponse.","Elle fait réfléchir celui qui l’écoute.","Je pose une question avant d’avoir un avis.","Quelle question vous habite ?"]},{"t":"Mon mot fétiche : racine","x":["Racine : un mot qui ancre.","Mes racines sont à Madagascar.","Elles me donnent la direction, pas la limite.","Je grandis vers le haut parce que je suis enraciné.","Où sont les vôtres ?"]},{"t":"Mon mot fétiche : essai","x":["Essai : un mot qui libère.","Un essai n’est pas un échec.","C’est une porte ouverte.","J’essaie tous les jours quelque chose de petit.","Qu’essayez-vous ?"]},{"t":"Mon mot fétiche : écoute","x":["Écoute : un mot qu’on sous-estime.","Écouter, c’est donner du temps.","J’écoute avant de répondre, toujours.","C’est la meilleure façon de comprendre.","Qui avez-vous écouté aujourd’hui ?"]},{"t":"Mon mot fétiche : départ","x":["Départ : un mot qui fait peur et qui fait envie.","Chaque départ est un risque et un cadeau.","J’en ai fait deux grands, et plusieurs petits.","Je ne regrette que ceux que je n’ai pas faits.","Quel départ préparez-vous ?"]}]};})();
